pageCss:
.subpage-hero {
  background: linear-gradient(135deg, var(--navy-dark) 0%, #1B3A5C 100%);
  padding: 160px 48px 80px;
  text-align: center;
}
.subpage-hero .section-label { color: rgba(255,255,255,0.5); }
.subpage-hero h1 {
  font-size: clamp(36px, 6vw, 56px);
  font-weight: 900;
  color: var(--white);
  letter-spacing: -0.03em;
  line-height: 1.05;
  margin-bottom: 16px;
}
.subpage-hero p {
  font-size: 17px;
  color: rgba(255,255,255,0.55);
  max-width: 480px;
  margin: 0 auto;
  line-height: 1.65;
}
.privacy-body {
  padding: 80px 48px 120px;
  background: var(--cream);
}
.privacy-body .container {
  max-width: 720px;
  margin: 0 auto;
}
.privacy-body h2 {
  font-size: 1.2rem;
  font-weight: 800;
  color: var(--navy-dark);
  letter-spacing: -0.01em;
  margin: 52px 0 14px;
}
.privacy-body h2:first-child { margin-top: 0; }
.privacy-body p {
  font-size: 15.5px;
  line-height: 1.75;
  color: var(--gray-700);
  margin-bottom: 16px;
}
.privacy-body ul {
  font-size: 15.5px;
  line-height: 1.75;
  color: var(--gray-700);
  margin: 0 0 16px 20px;
}
.privacy-body ul li { margin-bottom: 6px; }
.privacy-body a {
  color: var(--navy);
  text-decoration: underline;
}
.privacy-meta {
  font-size: 13px;
  color: var(--gray-400);
  margin-top: 64px;
  padding-top: 24px;
  border-top: 1px solid var(--gray-200);
}
